import copy

SYSTEMS = ["llm_only", "tfidf_rag", "graph_rag"]


def _sanitize(case):
    return {"id": case["id"], "question": case["question"]}


def run_experiment(cases, split, generate):
    selected = [case for case in cases if case.get("split") == split]
    answers = []
    for case in selected:
        sanitized = _sanitize(case)
        for system in SYSTEMS:
            answer = generate(copy.deepcopy(sanitized), system)
            answers.append({"id": case["id"], "system": system, "answer": answer})
    return {"manifest": {"split": split, "systems": list(SYSTEMS)}, "answers": answers}

