import hashlib

SYSTEMS = ["llm_only", "tfidf_rag", "graph_rag"]


def _sha256(value):
    if isinstance(value, bytes):
        data = value
    else:
        data = str(value).encode("utf-8")
    return hashlib.sha256(data).hexdigest()


def score_answers(cases, answers, judge, apply_overrides=False):
    case_by_id = {}
    for case in cases:
        case_id = case["id"]
        if case_id in case_by_id:
            raise ValueError("duplicate case id: %r" % (case_id,))
        case_by_id[case_id] = case

    seen = set()
    for answer in answers:
        case_id = answer.get("id")
        system = answer.get("system")
        if case_id not in case_by_id:
            raise ValueError("unknown case id: %r" % (case_id,))
        if system not in SYSTEMS:
            raise ValueError("unknown system: %r" % (system,))
        key = (case_id, system)
        if key in seen:
            raise ValueError("duplicate answer for %r" % (key,))
        seen.add(key)

    expected = {(case_id, system) for case_id in case_by_id for system in SYSTEMS}
    missing = expected - seen
    if missing:
        raise ValueError("missing answers: %r" % (sorted(missing),))

    rows = []
    for answer in answers:
        case = case_by_id[answer["id"]]
        score = judge(case, answer)
        if apply_overrides:
            override = case.get("legacy_override")
            if override:
                stored = override.get("answer_sha256")
                if stored is not None and stored == _sha256(answer.get("answer")):
                    score = {**score, **{k: v for k, v in override.items() if k != "answer_sha256"}}
        rows.append({**answer, **score, "adjudication": "scored"})
    return rows
